import React, { useEffect, useState } from "react";
import { Outlet, Link, useNavigate, useLocation } from "react-router-dom";
import {
  FaBookOpen,
  FaChalkboardTeacher,
  FaUserGraduate,
  FaCalendarAlt,
  FaSignOutAlt,
  FaGraduationCap,
  FaTasks,
  FaClipboardList,
  FaBrain,
  FaFolderOpen,
  FaClock,
  FaBell,
  FaChartLine,
  FaBars
} from "react-icons/fa";
import "./theme.css";

function MainLayout() {
  const navigate = useNavigate();
  const location = useLocation();

  const userName = localStorage.getItem("user_name");
  const role = localStorage.getItem("role");

  const getInitialTheme = () => {
    const saved = localStorage.getItem("theme_mode");
    if (saved) return saved;
    return "system";
  };

  const [themeMode, setThemeMode] = useState(getInitialTheme());
  const [sidebarOpen, setSidebarOpen] = useState(true);
  const [isMobile, setIsMobile] = useState(window.innerWidth < 900);

  const applyTheme = (mode) => {
    if (mode === "light") {
      document.documentElement.setAttribute("data-theme", "light");
      return;
    }
    if (mode === "dark") {
      document.documentElement.setAttribute("data-theme", "dark");
      return;
    }
    const prefersDark = window.matchMedia("(prefers-color-scheme: dark)").matches;
    document.documentElement.setAttribute("data-theme", prefersDark ? "dark" : "light");
  };

  useEffect(() => {
    applyTheme(themeMode);
    localStorage.setItem("theme_mode", themeMode);
  }, [themeMode]);

  useEffect(() => {
    const media = window.matchMedia("(prefers-color-scheme: dark)");

    const handleSystemThemeChange = () => {
      if (themeMode === "system") {
        applyTheme("system");
      }
    };

    if (media.addEventListener) {
      media.addEventListener("change", handleSystemThemeChange);
    } else {
      media.addListener(handleSystemThemeChange);
    }

    return () => {
      if (media.removeEventListener) {
        media.removeEventListener("change", handleSystemThemeChange);
      } else {
        media.removeListener(handleSystemThemeChange);
      }
    };
  }, [themeMode]);

  useEffect(() => {
    const handleResize = () => {
      const mobile = window.innerWidth < 900;
      setIsMobile(mobile);
      if (mobile) setSidebarOpen(false);
      else setSidebarOpen(true);
    };

    window.addEventListener("resize", handleResize);
    handleResize();
    return () => window.removeEventListener("resize", handleResize);
  }, []);

  const handleLogout = () => {
    localStorage.clear();
    navigate("/");
  };

  const linkClass = (path) =>
    location.pathname === path ? "sidebar-link active" : "sidebar-link";

  return (
    <div style={{ display: "flex", minHeight: "100vh" }}>
      <aside
        style={{
          width: isMobile ? "270px" : sidebarOpen ? "290px" : "88px",
          background: "var(--sidebar-bg)",
          color: "var(--sidebar-text)",
          padding: "16px",
          position: isMobile ? "fixed" : "sticky",
          left: isMobile ? (sidebarOpen ? "0" : "-300px") : "0",
          top: 0,
          height: "100vh",
          transition: "0.3s ease",
          zIndex: 1000,
          display: "flex",
          flexDirection: "column",
          justifyContent: "space-between",
          overflowY: "auto",
          boxShadow: "var(--shadow-lg)"
        }}
      >
        <div>
          <div
            style={{
              display: "flex",
              justifyContent: sidebarOpen ? "space-between" : "center",
              alignItems: "center",
              marginBottom: "18px"
            }}
          >
            {sidebarOpen ? (
              <div
                style={{
                  display: "flex",
                  alignItems: "center",
                  gap: "10px",
                  fontWeight: 800,
                  color: "#ffffff",
                  fontSize: "20px"
                }}
              >
                <FaGraduationCap />
                <span>EduFlow</span>
              </div>
            ) : (
              <div style={{ color: "#ffffff", fontSize: "20px" }}>
                <FaGraduationCap />
              </div>
            )}

            <button className="btn btn-secondary" onClick={() => setSidebarOpen(!sidebarOpen)}>
              <FaBars />
            </button>
          </div>

          {sidebarOpen && (
            <select
              className="select"
              value={themeMode}
              onChange={(e) => setThemeMode(e.target.value)}
              style={{ marginBottom: "16px" }}
            >
              <option value="system">🖥 System Theme</option>
              <option value="light">☀ Light Theme</option>
              <option value="dark">🌙 Dark Theme</option>
            </select>
          )}

          {role === "teacher" && (
            <Link to="/teacher-dashboard" className={linkClass("/teacher-dashboard")}>
              <FaChalkboardTeacher />
              {sidebarOpen && "Dashboard"}
            </Link>
          )}

          {role === "student" && (
            <Link to="/student-dashboard" className={linkClass("/student-dashboard")}>
              <FaUserGraduate />
              {sidebarOpen && "Dashboard"}
            </Link>
          )}

          <Link to="/courses" className={linkClass("/courses")}>
            <FaBookOpen />
            {sidebarOpen && "Courses"}
          </Link>

          {role === "student" && (
            <>
              <Link to="/planner" className={linkClass("/planner")}>
                <FaCalendarAlt />
                {sidebarOpen && "Planner"}
              </Link>

              <Link to="/smart-planner" className={linkClass("/smart-planner")}>
                <FaBrain />
                {sidebarOpen && "Smart Planner"}
              </Link>

              <Link to="/study-tracker" className={linkClass("/study-tracker")}>
                <FaClock />
                {sidebarOpen && "Study Tracker"}
              </Link>

              <Link to="/reminders" className={linkClass("/reminders")}>
                <FaBell />
                {sidebarOpen && "Reminders"}
              </Link>

              <Link to="/student-quiz" className={linkClass("/student-quiz")}>
                <FaTasks />
                {sidebarOpen && "Quiz"}
              </Link>

              <Link to="/student-assignments" className={linkClass("/student-assignments")}>
                <FaClipboardList />
                {sidebarOpen && "Assignments"}
              </Link>

              <Link to="/materials" className={linkClass("/materials")}>
                <FaFolderOpen />
                {sidebarOpen && "Materials"}
              </Link>

              <Link to="/pomodoro" className={linkClass("/pomodoro")}>
                <FaClock />
                {sidebarOpen && "Pomodoro"}
              </Link>
            </>
          )}

          {role === "teacher" && (
            <>
              <Link to="/teacher-quiz" className={linkClass("/teacher-quiz")}>
                <FaTasks />
                {sidebarOpen && "Quiz"}
              </Link>

              <Link to="/teacher-assignments" className={linkClass("/teacher-assignments")}>
                <FaClipboardList />
                {sidebarOpen && "Assignments"}
              </Link>

              <Link to="/quiz-analytics" className={linkClass("/quiz-analytics")}>
                <FaChartLine />
                {sidebarOpen && "Quiz Analytics"}
              </Link>

              <Link to="/upload-material" className={linkClass("/upload-material")}>
                <FaFolderOpen />
                {sidebarOpen && "Upload"}
              </Link>
            </>
          )}
        </div>
      </aside>

      {isMobile && sidebarOpen && (
        <div
          onClick={() => setSidebarOpen(false)}
          style={{
            position: "fixed",
            top: 0,
            left: 0,
            width: "100%",
            height: "100vh",
            background: "rgba(0,0,0,0.45)",
            zIndex: 999
          }}
        />
      )}

      <main style={{ flex: 1, minWidth: 0 }}>
        <div
          style={{
            background: "var(--topbar-bg)",
            backdropFilter: "blur(14px)",
            padding: "14px 18px",
            borderBottom: "1px solid var(--border)",
            display: "flex",
            justifyContent: "space-between",
            alignItems: "center",
            gap: "12px",
            position: "sticky",
            top: 0,
            zIndex: 50
          }}
        >
          <button className="btn btn-primary" onClick={() => setSidebarOpen(true)}>
            <FaBars />
          </button>

          <div style={{ display: "flex", alignItems: "center", gap: "12px" }}>
            <div style={{ fontWeight: 700, color: "var(--text)" }}>
              {userName || "User"}
            </div>

            <button
              className="btn btn-danger"
              onClick={handleLogout}
              style={{
                padding: isMobile ? "6px 10px" : "8px 12px",
                fontSize: isMobile ? "13px" : "14px"
              }}
            >
              <FaSignOutAlt />
              {!isMobile && "Logout"}
            </button>
          </div>
        </div>

        <Outlet />
      </main>
    </div>
  );
}

export default MainLayout;
